// SPDX-License-Identifier: Apache-2.0

//! `war frontier` (OW-WAR-0068): the stages that can start now.
//!
//! After mattpocock/skills `to-tickets` and `wayfinder` (MIT): a ticket is
//! unblocked when every ticket blocking it is closed, and the frontier is the
//! open, unblocked, unclaimed set. Here the ticket is a Stage, the blocking
//! edge is its milestone's `depends_on`, "closed" is a milestone whose every
//! obligation an admissible verification established, "claimed" is a
//! `dispatch.compiled` journal event naming the stage, and "done" is a
//! `submission.recorded` event naming it. Nothing here is a status claim: it
//! is derived from the same records `war resolve --dry-run` reads.
//!
//! Three choices, stated: `done` wins over `blocked` (a recorded submission
//! is history, whatever the graph says now); a milestone with no obligations
//! never completes, so everything behind it stays blocked until someone
//! writes the obligation (fail closed, and reported); a stage cited by more
//! than one milestone is one row, blocked if any of them waits.
//!
//! A second blocking edge (OW-WAR-0132): a blocking question on the stage that
//! no human has answered. The stage is `blocked` and its `waiting_on` names the
//! question beside any milestone; every other stage is untouched, and an
//! answered question blocks nothing. When the authority register holds no
//! actor who is not an agent, nobody can answer, and each such stage also
//! carries UNKNOWN `question.no-responder` naming `roles.toml`: neither
//! waiting normally nor answered (Law 15).

use std::collections::{BTreeMap, BTreeSet};

use serde::Serialize;

use crate::diagnostic::{Diagnostic, Report};
use crate::repo::{RepoError, Repository};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum StageState {
    /// Unblocked, undispatched: on the frontier.
    Open,
    /// Dispatched (a `dispatch.compiled` event), no submission yet.
    Claimed,
    /// A submission is recorded for it.
    Done,
    /// Its milestone waits on another milestone that is not complete, or a
    /// blocking question on it is unanswered.
    Blocked,
}

#[derive(Debug, Clone, Serialize)]
pub struct Row {
    pub warrant: String,
    pub stage: String,
    pub title: String,
    pub milestone: String,
    pub executor_kind: String,
    pub state: StageState,
    /// Milestones this one's milestone waits on and that are not complete,
    /// then the blocking questions on it that are unanswered (`Q-nnn`).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub waiting_on: Vec<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct Frontier {
    pub schema: String,
    pub rows: Vec<Row>,
    pub open: usize,
    pub claimed: usize,
    pub done: usize,
    pub blocked: usize,
}

pub const SCHEMA: &str = "oh.war/frontier/v1";

fn stage_events(dir: &camino::Utf8Path) -> Result<(BTreeSet<String>, BTreeSet<String>), RepoError> {
    let mut claimed = BTreeSet::new();
    let mut done = BTreeSet::new();
    let path = dir.join(crate::journal_cmd::FILE);
    match std::fs::symlink_metadata(&path) {
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok((claimed, done)),
        Err(source) => {
            return Err(RepoError::Io {
                context: format!("could not inspect {path}"),
                source,
            });
        }
        Ok(_) => {}
    }
    let metadata = std::fs::metadata(&path).map_err(|source| RepoError::Io {
        context: format!("could not inspect {path}"),
        source,
    })?;
    if !metadata.is_file() {
        return Err(RepoError::Message(format!(
            "{path}: journal must be a regular file"
        )));
    }
    // The legacy loader treats non-files as absent. Admission must distinguish
    // missing history from damaged containers and dangling links.
    let text = std::fs::read_to_string(&path).map_err(|source| RepoError::Io {
        context: format!("could not read {path}"),
        source,
    })?;
    let j =
        crate::journal_cmd::parse(&text).map_err(|e| RepoError::Message(format!("{path}: {e}")))?;
    for e in &j.events {
        if !matches!(
            e.event_type.as_str(),
            "dispatch.compiled" | "submission.recorded"
        ) {
            continue;
        }
        let payload: serde_json::Value = serde_json::from_str(&e.payload).map_err(|_| {
            RepoError::Message(format!(
                "{path}: {} event {} has invalid JSON payload",
                e.event_type, e.id
            ))
        })?;
        let stage = payload
            .get("stage")
            .and_then(serde_json::Value::as_str)
            .filter(|stage| !stage.trim().is_empty())
            .ok_or_else(|| {
                RepoError::Message(format!(
                    "{path}: {} event {} requires a nonempty string stage",
                    e.event_type, e.id
                ))
            })?;
        if e.event_type == "dispatch.compiled" {
            claimed.insert(stage.to_owned());
        } else {
            done.insert(stage.to_owned());
        }
    }
    Ok((claimed, done))
}

/// The frontier of one Warrant, or of every unresolved Warrant.
pub fn run(repo: &Repository, alias: Option<&str>) -> Result<(Report, Frontier), RepoError> {
    let mut report = Report::default();
    let dirs = match alias {
        Some(a) => vec![repo.warrant_dir(a)?],
        None => repo.warrant_dirs()?,
    };
    let mut rows = Vec::new();
    // Read once, and only if a blocking question needs it.
    let mut responder: Option<Result<bool, String>> = None;
    for dir in dirs {
        let one = repo.load_warrant(&dir)?;
        let alias = dir.file_name().unwrap_or_default().to_owned();
        if repo.load_resolution(&dir)?.is_some() {
            continue;
        }
        let basis = one.basis.as_ref().ok_or_else(|| {
            RepoError::Message(format!("{alias}: no readable workspace basis for frontier"))
        })?;
        let Some(text) = basis
            .atoms
            .iter()
            .find(|a| a.role == "milestones")
            .and_then(|a| String::from_utf8(a.bytes.clone()).ok())
        else {
            if one
                .validated
                .as_ref()
                .is_some_and(|v| !v.raw.atoms.iter().any(|a| a.role == "milestones"))
            {
                continue;
            }
            return Err(RepoError::Message(format!(
                "{alias}: no readable milestones atom for frontier"
            )));
        };
        let graph = openwarrant_core::milestones::parse(&text)
            .map_err(|e| RepoError::Message(format!("{alias}: invalid milestones: {e}")))?;
        let established: BTreeSet<String> = crate::resolve::assess(repo, &one)?
            .established
            .into_iter()
            .collect();
        let complete: BTreeMap<&str, bool> = graph
            .milestones
            .iter()
            .map(|m| {
                (
                    m.id.as_str(),
                    !m.obligation_refs.is_empty()
                        && m.obligation_refs.iter().all(|o| established.contains(o)),
                )
            })
            .collect();
        for m in graph
            .milestones
            .iter()
            .filter(|m| m.obligation_refs.is_empty())
        {
            if graph
                .milestones
                .iter()
                .any(|o| o.depends_on.contains(&m.id))
            {
                report.push(Diagnostic::warn(
                    "frontier.milestone-without-obligations",
                    repo.relative(&dir.join("atoms/45-milestones.yaml")),
                    format!(
                        "{alias}: {} has no obligation_refs, so it never completes and every milestone depending on it stays blocked",
                        m.id
                    ),
                ));
            }
        }
        let (claimed, done) = stage_events(&dir)?;
        let asked = open_blocking(repo, &alias, &mut report);
        // One row per stage: its milestones' waits are unioned.
        let mut per_stage: BTreeMap<String, (Vec<String>, BTreeSet<String>)> = BTreeMap::new();
        for m in &graph.milestones {
            let waiting: Vec<String> = m
                .depends_on
                .iter()
                .filter(|d| !complete.get(d.as_str()).copied().unwrap_or(false))
                .cloned()
                .collect();
            for sid in &m.stage_refs {
                let entry = per_stage.entry(sid.clone()).or_default();
                entry.0.push(m.id.clone());
                entry.1.extend(waiting.iter().cloned());
            }
        }
        for (sid, (milestones, waiting)) in per_stage {
            let Some(stage) = graph.stages.iter().find(|s| s.id == sid) else {
                continue;
            };
            let questions = asked.get(&sid).cloned().unwrap_or_default();
            let mut waiting: Vec<String> = waiting.into_iter().collect();
            waiting.extend(questions.iter().cloned());
            let state = if done.contains(&sid) {
                StageState::Done
            } else if !waiting.is_empty() {
                StageState::Blocked
            } else if claimed.contains(&sid) {
                StageState::Claimed
            } else {
                StageState::Open
            };
            if state == StageState::Blocked && !questions.is_empty() {
                let answerable = responder.get_or_insert_with(|| someone_can_answer(repo));
                if let Some(why) = no_responder(answerable) {
                    report.push(Diagnostic::unknown(
                        "question.no-responder",
                        "docs/authority/roles.toml".to_owned(),
                        format!(
                            "{alias}/{sid} waits on {} and {why}, so nobody can answer:                              `war answer` refuses an agent by kind (§27.2). The stage stays                              blocked; it is not waiting normally and it is not answered. A human                              added to docs/authority/roles.toml can answer",
                            questions.join(", ")
                        ),
                    ));
                }
            }
            rows.push(Row {
                warrant: alias.clone(),
                stage: sid.clone(),
                title: stage.title.clone().unwrap_or_default(),
                milestone: milestones.join("+"),
                executor_kind: stage.executor_kind.to_string(),
                state,
                waiting_on: if state == StageState::Blocked {
                    waiting
                } else {
                    vec![]
                },
            });
        }
    }
    rows.sort_by(|a, b| (&a.warrant, &a.stage).cmp(&(&b.warrant, &b.stage)));
    let count = |s: StageState| rows.iter().filter(|r| r.state == s).count();
    let f = Frontier {
        schema: SCHEMA.to_owned(),
        open: count(StageState::Open),
        claimed: count(StageState::Claimed),
        done: count(StageState::Done),
        blocked: count(StageState::Blocked),
        rows,
    };
    report.note(format!(
        "{} open, {} claimed, {} done, {} blocked across {} stage(s)",
        f.open,
        f.claimed,
        f.done,
        f.blocked,
        f.rows.len()
    ));
    Ok((report, f))
}

/// The unanswered blocking questions of one Warrant, by stage. A question
/// store that cannot be read is reported, not taken to hold nothing.
fn open_blocking(
    repo: &Repository,
    alias: &str,
    report: &mut Report,
) -> BTreeMap<String, Vec<String>> {
    let (questions, unreadable) = crate::questions::load_tolerant(repo, alias);
    for path in unreadable {
        report.push(Diagnostic::unknown(
            "frontier.question-unreadable",
            path,
            format!(
                "{alias}: a question record cannot be read, so whether it blocks a stage cannot                  be established; the rows below count only the readable ones"
            ),
        ));
    }
    let mut by_stage: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for q in questions.into_iter().filter(|q| q.blocking && q.is_open()) {
        by_stage.entry(q.stage).or_default().push(q.id);
    }
    by_stage
}

/// Whether the register names an actor `war answer` would accept: any
/// assignment whose kind is not `agent` (A-002). `Err` when the register
/// cannot be read at all.
fn someone_can_answer(repo: &Repository) -> Result<bool, String> {
    repo.load_authority_register()
        .map(|r| {
            r.assignments
                .iter()
                .any(|a| a.actor_kind != openwarrant_core::authority::ActorKind::Agent)
        })
        .map_err(|e| e.to_string())
}

/// The clause of the no-responder finding, or `None` when someone can answer.
fn no_responder(answerable: &Result<bool, String>) -> Option<String> {
    match answerable {
        Ok(true) => None,
        Ok(false) => Some(
            "docs/authority/roles.toml holds no actor whose actor_kind is not `agent`".to_owned(),
        ),
        Err(e) => Some(format!("docs/authority/roles.toml cannot be read ({e})")),
    }
}

#[must_use]
pub fn render(f: &Frontier) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "frontier: {} open · {} claimed · {} done · {} blocked\n\n",
        f.open, f.claimed, f.done, f.blocked
    ));
    for r in &f.rows {
        let state = match r.state {
            StageState::Open => "OPEN   ",
            StageState::Claimed => "CLAIMED",
            StageState::Done => "done   ",
            StageState::Blocked => "blocked",
        };
        out.push_str(&format!(
            "  {state}  {:<12} {:<10} {:<4} {:<8} {}{}\n",
            r.warrant,
            r.stage,
            r.milestone,
            r.executor_kind,
            r.title,
            if r.waiting_on.is_empty() {
                String::new()
            } else {
                format!("  (waits on {})", r.waiting_on.join(", "))
            }
        ));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_four_states_are_distinct_words() {
        for s in [
            StageState::Open,
            StageState::Claimed,
            StageState::Done,
            StageState::Blocked,
        ] {
            let j = serde_json::to_string(&s).unwrap();
            assert!(["\"open\"", "\"claimed\"", "\"done\"", "\"blocked\""].contains(&j.as_str()));
        }
    }
}

// SPDX-License-Identifier: Apache-2.0
//! `war next` — what should happen next in this repository, and whose act it
//! is.
//!
//! Two lists exist already: `war sign --list` (the human's acts) and the
//! corpus projection's `next_actionable` (stages an agent could execute).
//! Neither answers the question an agent asks first: "of everything pending,
//! which is MINE?" This merges them into one ordered list where every action
//! names its actor, and it is asserted over the whole table that no action
//! whose actor is `agent` is a signing act. An agent that reads this cannot be
//! told to authorize, resolve, accept or correct; it can only be told that a
//! human must, and how.
//!
//! t-67ed: ready ticket items come first. They are read from the ticket
//! store with the same computation `war ready` uses, carry `war claim`, and
//! are never a signature; the Warrant acts follow them, still judged.

use serde::Serialize;

use crate::repo::{RepoError, Repository};
use crate::sign::{self, Pending};

pub const SCHEMA: &str = "oh.war/next/v1";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Actor {
    Human,
    Agent,
}

/// What the act's dry run said about a signing command (OW-ADR-0022): the
/// ingest ran with the write withheld, and this is its verdict.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(tag = "verdict", rename_all = "snake_case")]
pub enum Judged {
    /// Every refusal passed; the signature is the only thing missing.
    WouldRecord,
    /// The ingest would refuse, and `rule` is the first rule that refused.
    WouldRefuse { rule: String },
}

impl Judged {
    #[must_use]
    pub fn word(&self) -> String {
        match self {
            Self::WouldRecord => "would record".to_owned(),
            Self::WouldRefuse { rule } => format!("would refuse: {rule}"),
        }
    }
}

#[derive(Debug, Clone, Serialize)]
pub struct Action {
    pub actor: Actor,
    pub warrant: String,
    /// A short verb phrase: `authorize`, `resolve`, `correct`, `accept`,
    /// `check`, `deliver`, `verify`, `execute`.
    pub action: String,
    /// The command that does it, verbatim.
    pub command: String,
    pub why: String,
    /// On every action whose command begins `war sign`: the dry run's
    /// verdict on exactly that command. Absent on an agent's action, which
    /// has no signature to judge.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub judged: Option<Judged>,
}

/// A ticket item that can start now (`war ready`'s row), offered before any
/// Warrant act. Its command is always `war claim`: never a signature.
#[derive(Debug, Clone, Serialize)]
pub struct ReadyItem {
    pub actor: Actor,
    pub ticket: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub item: Option<String>,
    pub title: String,
    pub text: String,
    pub priority: u8,
    pub command: String,
}

impl ReadyItem {
    fn of(r: &crate::ticket::ReadyRow) -> Self {
        Self {
            actor: Actor::Agent,
            ticket: r.ticket.clone(),
            item: r.item.clone(),
            title: r.title.clone(),
            text: r.text.clone(),
            priority: r.priority,
            command: format!("war claim {}", r.target()),
        }
    }
}

#[derive(Debug, Clone, Serialize)]
pub struct Next {
    pub schema: &'static str,
    /// Ticket items that can start now, most urgent first (t-67ed). Listed
    /// before `actions`; nothing here needs anyone's signature.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub ready: Vec<ReadyItem>,
    pub actions: Vec<Action>,
    /// Why `actions` is empty, when it is. Never silently empty.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub nothing: Option<String>,
    /// What stands in the way that no action here can clear (OW-WAR-0132):
    /// today `question.no-responder`, a blocking question nobody in the
    /// authority register may answer. UNKNOWN, never silently "waiting".
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub findings: Vec<Finding>,
}

/// A finding carried into `war next`, in the envelope diagnostic's shape.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Finding {
    pub rule: String,
    /// `unknown` / `warn` / `error`, as the envelope spells a severity.
    pub severity: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub file: Option<String>,
    pub message: String,
}

/// The pure part: given the pending human acts and the corpus projection,
/// derive the table. Separated from I/O so the "an agent never signs"
/// invariant can be asserted on synthetic inputs.
#[must_use]
pub fn derive(pending: &[Pending], status: &openwarrant_core::status::CorpusStatus) -> Next {
    let mut actions = Vec::new();
    // Human acts first: they unblock the most.
    for p in pending {
        let (warrant, action, target, why) = match p {
            Pending::Authorize {
                alias,
                revision,
                amendment,
                ..
            } => (
                alias.clone(),
                "authorize",
                alias.clone(),
                format!(
                    "revision {revision} awaits authorization{}",
                    amendment
                        .as_ref()
                        .map(|a| format!(" under {}", a.id))
                        .unwrap_or_default()
                ),
            ),
            Pending::Resolve { alias, request, .. } => (
                alias.clone(),
                "resolve",
                alias.clone(),
                if request.would_resolve_satisfied == Some(true) {
                    "the thirteen are met and §38.6 would resolve satisfied".to_owned()
                } else {
                    format!(
                        "the thirteen are met; {} obligation(s) unestablished, so the outcome must be named",
                        request.unestablished.len()
                    )
                },
            ),
            Pending::Accept { version, .. } => (
                format!("SAS {version}"),
                "accept",
                version.clone(),
                "a proposed SAS revision awaits acceptance".to_owned(),
            ),
            Pending::AcceptRoadmap { revision, request } => (
                "roadmap".to_owned(),
                "accept",
                "roadmap".to_owned(),
                format!(
                    "roadmap revision {revision} awaits acceptance: {}",
                    request.diff.summary()
                ),
            ),
            Pending::AcceptStanding { request } => (
                request.reference.clone(),
                "accept",
                crate::standing_cmd::target(&request.id, request.revision),
                format!(
                    "standing authorization {} awaits its one signature",
                    request.reference
                ),
            ),
            Pending::RevokeStanding { request } => (
                request.reference.clone(),
                "revoke",
                crate::standing_cmd::target(&request.id, request.revision),
                "a signed class, offered for revocation".to_owned(),
            ),
            Pending::Correct {
                alias,
                deliverable_id,
                request,
                ..
            } => (
                alias.clone(),
                "correct",
                format!("{alias}/{deliverable_id}"),
                format!("{} drifted after resolution", request.target_ref),
            ),
            Pending::Invalidate { gate, request } => (
                gate.clone(),
                "invalidate",
                gate.clone(),
                format!(
                    "invalidating {gate} would dispute {} resolution(s)",
                    request.disputes.len()
                ),
            ),
        };
        actions.push(Action {
            actor: Actor::Human,
            warrant,
            action: action.to_owned(),
            command: format!("war sign {target}"),
            why,
            judged: None,
        });
    }
    // Agent acts: whatever stands between a Warrant and the human's next act.
    for w in &status.warrants {
        use openwarrant_core::status::WarrantRung as R;
        let already_human = actions
            .iter()
            .any(|a| a.actor == Actor::Human && a.warrant == w.alias);
        match w.rung {
            R::Invalid => actions.push(Action {
                actor: Actor::Agent,
                warrant: w.alias.clone(),
                action: "check".to_owned(),
                command: format!("war check {}", w.alias),
                why: "the manifest does not validate".to_owned(),
                judged: None,
            }),
            // A pending human act on this Warrant is the unblocker; an agent
            // action beside it would be noise, so Draft is only an agent's when
            // no human act is pending.
            R::Draft if !already_human => {
                let unmet = w.unmet.join("; ");
                actions.push(Action {
                    actor: Actor::Agent,
                    warrant: w.alias.clone(),
                    action: "deliver".to_owned(),
                    command: format!("war evidence record {a} && war verify {a}", a = w.alias),
                    why: if unmet.is_empty() {
                        "not every §56.1 requirement is met".to_owned()
                    } else {
                        format!("unmet: {unmet}")
                    },
                    judged: None,
                });
            }
            R::ReadyToResolve if w.would_resolve_satisfied != Some(true) => {
                actions.push(Action {
                    actor: Actor::Agent,
                    warrant: w.alias.clone(),
                    action: "verify".to_owned(),
                    command: format!("war verify {}", w.alias),
                    why: "obligations remain unestablished; a blind verifier must dispose of them"
                        .to_owned(),
                    judged: None,
                });
            }
            _ => {}
        }
    }
    for s in &status.next_actionable {
        actions.push(Action {
            actor: Actor::Agent,
            warrant: s.warrant.clone(),
            action: "execute".to_owned(),
            command: format!("war dispatch {} {}", s.warrant, s.stage),
            why: format!("{} / {}: {}", s.milestone, s.stage, s.why),
            judged: None,
        });
    }
    // `assert!`, not `debug_assert!`: this invariant is the point of the
    // command and must hold in a release-built test binary too.
    assert!(
        actions
            .iter()
            .all(|a| a.actor != Actor::Agent || !a.command.starts_with("war sign")),
        "an agent is never handed a signing act"
    );
    let nothing = if actions.is_empty() {
        Some(
            status
                .nothing_actionable
                .as_ref()
                .map(|n| {
                    // `n.why` is already the sentence. Debug-printing the
                    // struct put `NothingActionable { objective: None,
                    // blocked_by: [], why: "..." }` on the terminal of anyone
                    // whose corpus had nothing to do — on the first command
                    // QUICKSTART tells a new reader to trust.
                    let mut s = n.why.clone();
                    if let Some(o) = &n.objective {
                        s.push_str(&format!(" ({o})"));
                    }
                    if !n.blocked_by.is_empty() {
                        s.push_str(&format!("; blocked by {}", n.blocked_by.join(", ")));
                    }
                    s
                })
                .unwrap_or_else(|| {
                    "nothing awaits a signature and no stage is actionable".to_owned()
                }),
        )
    } else {
        None
    };
    Next {
        schema: SCHEMA,
        ready: Vec::new(),
        actions,
        nothing,
        findings: Vec::new(),
    }
}

/// OW-WAR-0132: the frontier's question edge, applied to the table. A stage
/// a blocking question holds is not offered to an agent (`war dispatch` would
/// start work the question is meant to stop), and the frontier's
/// `question.no-responder` is carried as a finding. Pure over the frontier,
/// so the rule is testable without a repository.
pub fn apply_questions(
    next: &mut Next,
    frontier: &crate::frontier::Frontier,
    report: &crate::diagnostic::Report,
) {
    let held: std::collections::BTreeSet<(&str, &str)> = frontier
        .rows
        .iter()
        .filter(|r| {
            r.state == crate::frontier::StageState::Blocked
                && r.waiting_on.iter().any(|w| is_question(w))
        })
        .map(|r| (r.warrant.as_str(), r.stage.as_str()))
        .collect();
    next.actions.retain(|a| {
        a.action != "execute" || {
            let stage = a.command.rsplit(' ').next().unwrap_or_default();
            !held.contains(&(a.warrant.as_str(), stage))
        }
    });
    for d in &report.diagnostics {
        if d.rule == "question.no-responder" {
            next.findings.push(Finding {
                rule: d.rule.clone(),
                severity: d.severity.label().to_ascii_lowercase(),
                file: d.file.clone(),
                message: d.message.clone(),
            });
        }
    }
    if next.actions.is_empty() && next.nothing.is_none() {
        next.nothing = Some(if held.is_empty() {
            "nothing awaits a signature and no stage is actionable".to_owned()
        } else {
            format!(
                "every actionable stage waits on a blocking question: {}",
                held.iter()
                    .map(|(w, s)| format!("{w}/{s}"))
                    .collect::<Vec<_>>()
                    .join(", ")
            )
        });
    }
}

/// `Q-nnn`, as the frontier names a question in `waiting_on`; a milestone is
/// `M-…` / `MS-…` and never matches.
fn is_question(id: &str) -> bool {
    id.strip_prefix("Q-")
        .is_some_and(|n| !n.is_empty() && n.bytes().all(|b| b.is_ascii_digit()))
}

pub fn run(repo: &Repository) -> Result<Next, RepoError> {
    let status = crate::status::build(repo)?;
    run_with(repo, &status)
}

/// [`run`] over a corpus status already built, so a caller that also needs
/// the status (`war compile`'s master document) builds it once.
pub fn run_with(
    repo: &Repository,
    status: &openwarrant_core::status::CorpusStatus,
) -> Result<Next, RepoError> {
    let pending = sign::pending(repo)?;
    let mut next = derive(&pending, status);
    let (report, frontier) = crate::frontier::run(repo, None)?;
    apply_questions(&mut next, &frontier, &report);
    // OW-WAR-0141: a question waiting before its Warrant exists is a human's
    // act too (`answer`), read from `docs/intake/` by questions.rs.
    next.actions.extend(crate::questions::intake_actions(repo));
    if !next.actions.is_empty() {
        next.nothing = None;
    }
    judge(repo, &pending, &mut next);
    ready_tickets(repo, &mut next);
    Ok(next)
}

/// t-67ed: the ticket store's ready set, ahead of every Warrant act. The
/// same `ticket::ready_rows` `war ready` answers from, so the two never
/// disagree. A store that cannot be read is an UNKNOWN finding, never an
/// empty list presented as "nothing ready".
pub fn ready_tickets(repo: &Repository, next: &mut Next) {
    let rows = crate::ticket::Store::open(repo, None).and_then(|store| {
        let (tickets, _faults) = store.load_all()?;
        crate::ticket::ready_rows(&store, &tickets)
    });
    match rows {
        Ok(rows) => next.ready = rows.iter().map(ReadyItem::of).collect(),
        Err(e) => next.findings.push(Finding {
            rule: "next.tickets-unreadable".to_owned(),
            severity: "unknown".to_owned(),
            file: None,
            message: format!("the ticket store could not be read, so ready items are UNKNOWN: {e}"),
        }),
    }
}

/// The dry run in front of every handed-over command (OW-ADR-0022). The
/// whole queue is judged by one `war sign --all --dry-run` — each act
/// drafted, its ingest run with the write withheld — and each verdict is
/// carried beside the `war sign <target>` that act is. Acts the dry run would
/// refuse are listed after the ones it would record, so the first command a
/// human reads is one that will work. Writes nothing and holds no key: the
/// dry run's own guarantees (`sign::Options::dry_run`).
///
/// One sweep rather than one dry run per target: each `sign::run` re-reads
/// the whole queue, and a queue of a dozen acts judged one by one cost a
/// dozen reads of it. The sweep is over `pending` itself — the queue the
/// actions were derived from, read by the caller in this process — not a
/// second read of it (`sign::dry_run_all`, t-280c).
pub fn judge(repo: &Repository, pending: &[Pending], next: &mut Next) {
    let verdicts = match sign::dry_run_all(repo, pending) {
        Ok(report) => verdicts(pending, &report),
        Err(_) => std::collections::BTreeMap::new(),
    };
    for a in &mut next.actions {
        let Some(target) = a.command.strip_prefix("war sign ") else {
            continue;
        };
        let target = target.split_whitespace().next().unwrap_or(target);
        a.judged = Some(
            verdicts
                .get(target)
                .cloned()
                .unwrap_or_else(|| Judged::WouldRefuse {
                    rule: "sign.dry-run-failed".to_owned(),
                }),
        );
    }
    order(next);
}

/// The `war sign` target each pending act is handed over as — the same
/// words `derive` writes after `war sign `.
fn target_of(p: &Pending) -> String {
    match p {
        Pending::Authorize { alias, .. } | Pending::Resolve { alias, .. } => alias.clone(),
        Pending::Accept { version, .. } => version.clone(),
        Pending::AcceptRoadmap { .. } => "roadmap".to_owned(),
        Pending::Correct {
            alias,
            deliverable_id,
            ..
        } => format!("{alias}/{deliverable_id}"),
        Pending::Invalidate { gate, .. } => gate.clone(),
        Pending::AcceptStanding { .. } | Pending::RevokeStanding { .. } => {
            crate::sign::target_of(p)
        }
    }
}

/// Split a whole-queue dry run into one verdict per act. The sweep reports
/// each act as its ingest's diagnostics followed by one closing diagnostic
/// that names the act (`sign::line`): `sign.would-record`, or a refusal —
/// `sign.would-refuse`, `sign.who`, `sign.not-draftable`,
/// `sign.needs-decision`, `sign.dry-run-failed`.
fn verdicts(
    pending: &[Pending],
    report: &crate::diagnostic::Report,
) -> std::collections::BTreeMap<String, Judged> {
    const CLOSING: [&str; 6] = [
        "sign.would-record",
        "sign.would-refuse",
        "sign.who",
        "sign.not-draftable",
        "sign.needs-decision",
        "sign.dry-run-failed",
    ];
    let lines: Vec<(String, String)> = pending
        .iter()
        .map(|p| (sign::line(p), target_of(p)))
        .collect();
    let mut out = std::collections::BTreeMap::new();
    let mut segment = crate::diagnostic::Report::default();
    for d in &report.diagnostics {
        if !CLOSING.contains(&d.rule.as_str()) {
            segment.push(d.clone());
            continue;
        }
        let named = |l: &str| d.file.as_deref() == Some(l) || d.message.starts_with(l);
        if let Some((_, target)) = lines.iter().find(|(l, _)| named(l)) {
            segment.push(d.clone());
            out.insert(target.clone(), verdict(Ok(std::mem::take(&mut segment))));
        }
        segment = crate::diagnostic::Report::default();
    }
    out
}

/// Read a dry run's report as a verdict: `sign.would-record` is the only
/// recording word; otherwise the first error that is not the summary
/// `sign.would-refuse` names why.
fn verdict(report: Result<crate::diagnostic::Report, RepoError>) -> Judged {
    let report = match report {
        Ok(r) => r,
        Err(_) => {
            return Judged::WouldRefuse {
                rule: "sign.dry-run-failed".to_owned(),
            };
        }
    };
    if report
        .diagnostics
        .iter()
        .any(|d| d.rule == "sign.would-record")
    {
        return Judged::WouldRecord;
    }
    let rule = report
        .diagnostics
        .iter()
        .filter(|d| {
            d.severity == crate::diagnostic::Severity::Error || d.rule == "sign.needs-decision"
        })
        .map(|d| d.rule.clone())
        .find(|r| r != "sign.would-refuse")
        .unwrap_or_else(|| "sign.would-refuse".to_owned());
    Judged::WouldRefuse { rule }
}

/// Humans first; among them, what would record before what would refuse.
/// A stable sort, so the order within each group is `derive`'s.
fn order(next: &mut Next) {
    next.actions.sort_by_key(|a| match (a.actor, &a.judged) {
        (Actor::Human, Some(Judged::WouldRecord) | None) => 0,
        (Actor::Human, Some(Judged::WouldRefuse { .. })) => 1,
        (Actor::Agent, _) => 2,
    });
}

#[must_use]
pub fn render(n: &Next) -> String {
    let mut s = String::new();
    for r in &n.ready {
        s.push_str(&format!(
            "{:<6} {:<12} {:<10} {}\n{:>6} p{} {}{}\n",
            "ready",
            r.ticket,
            "claim",
            r.command,
            "",
            r.priority,
            r.text,
            if r.item.is_some() {
                format!(" — {}", r.title)
            } else {
                String::new()
            },
        ));
    }
    for a in &n.actions {
        s.push_str(&format!(
            "{:<6} {:<12} {:<10} {}{}\n{:>6} {}\n",
            match a.actor {
                Actor::Human => "HUMAN",
                Actor::Agent => "agent",
            },
            a.warrant,
            a.action,
            a.command,
            a.judged
                .as_ref()
                .map(|j| format!("  [{}]", j.word()))
                .unwrap_or_default(),
            "",
            a.why
        ));
    }
    if let Some(why) = &n.nothing {
        if n.ready.is_empty() {
            s.push_str(&format!("nothing to do: {why}\n"));
        } else {
            s.push_str(&format!("no Warrant act waits: {why}\n"));
        }
    }
    for f in &n.findings {
        s.push_str(&format!(
            "{} {}{}: {}\n",
            f.severity.to_ascii_uppercase(),
            f.rule,
            f.file
                .as_deref()
                .map(|p| format!(" ({p})"))
                .unwrap_or_default(),
            f.message
        ));
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    fn row(
        stage: &str,
        state: crate::frontier::StageState,
        waiting: &[&str],
    ) -> crate::frontier::Row {
        crate::frontier::Row {
            warrant: "X-WAR-0001".to_owned(),
            stage: stage.to_owned(),
            title: String::new(),
            milestone: "MS-001".to_owned(),
            executor_kind: "agent".to_owned(),
            state,
            waiting_on: waiting.iter().map(|s| (*s).to_owned()).collect(),
        }
    }

    fn execute(stage: &str) -> Action {
        Action {
            actor: Actor::Agent,
            warrant: "X-WAR-0001".to_owned(),
            action: "execute".to_owned(),
            command: format!("war dispatch X-WAR-0001 {stage}"),
            why: String::new(),
            judged: None,
        }
    }

    #[test]
    fn a_question_held_stage_is_not_offered_and_no_responder_is_carried() {
        use crate::frontier::StageState::{Blocked, Open};
        let frontier = crate::frontier::Frontier {
            schema: crate::frontier::SCHEMA.to_owned(),
            rows: vec![
                row("STAGE-001", Blocked, &["Q-001"]),
                row("STAGE-002", Open, &[]),
                row("STAGE-003", Blocked, &["MS-000"]),
            ],
            open: 1,
            claimed: 0,
            done: 0,
            blocked: 2,
        };
        let mut report = crate::diagnostic::Report::default();
        report.push(crate::diagnostic::Diagnostic::unknown(
            "question.no-responder",
            "docs/authority/roles.toml".to_owned(),
            "nobody can answer",
        ));
        let mut next = Next {
            schema: SCHEMA,
            ready: Vec::new(),
            actions: vec![
                execute("STAGE-001"),
                execute("STAGE-002"),
                execute("STAGE-003"),
            ],
            nothing: None,
            findings: Vec::new(),
        };
        apply_questions(&mut next, &frontier, &report);
        let offered: Vec<&str> = next.actions.iter().map(|a| a.command.as_str()).collect();
        // The question-held stage is gone; a milestone wait is not this rule's.
        assert_eq!(
            offered,
            [
                "war dispatch X-WAR-0001 STAGE-002",
                "war dispatch X-WAR-0001 STAGE-003"
            ]
        );
        assert_eq!(next.findings.len(), 1);
        assert_eq!(next.findings[0].severity, "unknown");
        assert_eq!(
            next.findings[0].file.as_deref(),
            Some("docs/authority/roles.toml")
        );
        assert!(render(&next).contains("UNKNOWN question.no-responder"));

        // Refusal side: with only the held stage, the list says why it is
        // empty instead of going silent, and nothing is offered.
        let mut next = Next {
            schema: SCHEMA,
            ready: Vec::new(),
            actions: vec![execute("STAGE-001")],
            nothing: None,
            findings: Vec::new(),
        };
        apply_questions(&mut next, &frontier, &crate::diagnostic::Report::default());
        assert!(next.actions.is_empty());
        assert!(next.findings.is_empty());
        assert!(
            next.nothing
                .as_deref()
                .unwrap_or_default()
                .contains("X-WAR-0001/STAGE-001")
        );
    }

    #[test]
    fn an_agent_is_never_handed_a_signing_act_and_humans_come_first() {
        // The real corpus is the fixture: every kind of pending act exists in
        // it or in its history, and the invariant must hold over all of it.
        let root = camino::Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .canonicalize_utf8()
            .unwrap();
        let repo = Repository::open(root).unwrap();
        let n = run(&repo).unwrap();
        assert!(!n.actions.is_empty());
        for a in &n.actions {
            if a.actor == Actor::Agent {
                assert!(
                    !a.command.starts_with("war sign"),
                    "agent handed a signature: {a:?}"
                );
                assert!(
                    !["authorize", "resolve", "accept", "correct"].contains(&a.action.as_str())
                );
            } else {
                assert!(a.command.starts_with("war sign"), "{a:?}");
                assert!(
                    a.judged.is_some(),
                    "a signing command handed over unjudged: {a:?}"
                );
            }
        }
        // t-67ed: a ready ticket item is an agent's, and is a claim — never
        // a signature, never an authority verb.
        for r in &n.ready {
            assert_eq!(r.actor, Actor::Agent);
            assert!(r.command.starts_with("war claim "), "{r:?}");
            assert!(!r.command.contains("war sign"), "{r:?}");
        }
        let first_agent = n.actions.iter().position(|a| a.actor == Actor::Agent);
        let last_human = n.actions.iter().rposition(|a| a.actor == Actor::Human);
        if let (Some(fa), Some(lh)) = (first_agent, last_human) {
            assert!(lh < fa, "human acts are listed before agent acts");
        }
        let first_refused = n
            .actions
            .iter()
            .position(|a| matches!(a.judged, Some(Judged::WouldRefuse { .. })));
        let last_recordable = n
            .actions
            .iter()
            .rposition(|a| matches!(a.judged, Some(Judged::WouldRecord)));
        if let (Some(fr), Some(lr)) = (first_refused, last_recordable) {
            assert!(
                lr < fr,
                "a refusable act is listed after every recordable one"
            );
        }
    }

    #[test]
    fn a_verdict_names_the_ingest_rule_not_the_summary() {
        use crate::diagnostic::{Diagnostic, Report};
        let mut r = Report::default();
        r.push(Diagnostic::error("authorize.no-amendment", "x", "why"));
        r.push(Diagnostic::error("sign.would-refuse", "x", "summary"));
        assert_eq!(
            verdict(Ok(r)),
            Judged::WouldRefuse {
                rule: "authorize.no-amendment".into()
            }
        );
        let mut ok = Report::default();
        ok.push(Diagnostic::pass("sign.would-record", "fine"));
        assert_eq!(verdict(Ok(ok)), Judged::WouldRecord);
    }

    fn ready_item() -> ReadyItem {
        ReadyItem {
            actor: Actor::Agent,
            ticket: "t-0001".to_owned(),
            item: Some("i-0001".to_owned()),
            title: "A ticket".to_owned(),
            text: "The first item".to_owned(),
            priority: 1,
            command: "war claim t-0001/i-0001".to_owned(),
        }
    }

    fn human_act() -> Action {
        Action {
            actor: Actor::Human,
            warrant: "X-WAR-0001".to_owned(),
            action: "authorize".to_owned(),
            command: "war sign X-WAR-0001".to_owned(),
            why: "revision 1 awaits authorization".to_owned(),
            judged: Some(Judged::WouldRecord),
        }
    }

    #[test]
    fn a_ready_ticket_item_is_listed_before_a_human_act() {
        let next = Next {
            schema: SCHEMA,
            ready: vec![ready_item()],
            actions: vec![human_act()],
            nothing: None,
            findings: Vec::new(),
        };
        let out = render(&next);
        let claim = out
            .find("war claim t-0001/i-0001")
            .expect("the ready item is listed");
        let sign = out
            .find("war sign X-WAR-0001")
            .expect("the human act stays listed");
        assert!(claim < sign, "ready items come first:\n{out}");
        assert!(
            out.contains("[would record]"),
            "the human act is still judged"
        );
        // JSON: `ready` sits beside `actions`, and names an agent's claim.
        let v = serde_json::to_value(&next).unwrap();
        assert_eq!(v["ready"][0]["command"], "war claim t-0001/i-0001");
        assert_eq!(v["ready"][0]["actor"], "agent");
        assert_eq!(v["actions"][0]["actor"], "human");
    }

    #[test]
    fn with_no_ready_item_nothing_is_said_plainly_and_ready_is_omitted() {
        let next = Next {
            schema: SCHEMA,
            ready: Vec::new(),
            actions: Vec::new(),
            nothing: Some("nothing awaits".to_owned()),
            findings: Vec::new(),
        };
        assert!(render(&next).starts_with("nothing to do: nothing awaits"));
        let v = serde_json::to_value(&next).unwrap();
        assert!(v.get("ready").is_none());
        // Refusal side: with a ready item, "nothing to do" is not said.
        let next = Next {
            ready: vec![ready_item()],
            ..next
        };
        let out = render(&next);
        assert!(!out.contains("nothing to do"), "{out}");
        assert!(out.contains("no Warrant act waits: nothing awaits"));
    }
}
